package com.skyclone.mod.kuudra;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;

import java.io.Reader;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The hunt's data, read from {@code data/kuudra/tiers.json}, {@code perks.json} and {@code loot.json}
 * (all generated by {@code tools/gen/kuudra/gen_kuudra.py}). Pure: no Bukkit, so unit tests load the
 * shipping files directly.
 */
public final class KCatalog {

    /** One hunt tier (research 04 sec 4.2 - 4.5). */
    public static final class Tier {
        public String id;
        public int index;
        public String name;
        public String color;
        public String key;
        public int rep;
        public String requirement;
        public int sbXp;
        public int waveSeconds;
        public int collection;
        public double bossHp;
        public double bossDamage;
        public double mobHp;
        public double mobDamage;
        public boolean stun;
        public boolean lair;
        /** Free chest Crimson Essence (official June-2025 10/25/50/100/200). */
        public int[] freeEssence;
        /** GUARANTEED paid-chest Crimson Essence (estimate; dial kuudra.paid-essence-scale). */
        public int[] paidEssence;
        /** GUARANTEED Leviathan Teeth per paid chest (1/1/2/2/3). */
        public int[] teeth;
        /** GUARANTEED Kraken shards per paid chest (1/1/2/2/3, June 2025). */
        public int kraken;
        /** Mana-book level in this tier's slot 2 (I at Basic .. V at Infernal). */
        public int bookLevel;

        public String colored() { return "&" + color + name; }
        public String bossId() { return "leviathan_" + id; }
    }

    /** Fight constants; every one is scaled by a dial at use time. */
    public static final class Fight {
        public int supplies = 6;
        public int fuelPerVolley = 4;
        public double volleyPercent = 15;
        public double unstunnedPercent = 1.5;
        public double dpsAtPercent = 40;
        public double lairAtPercent = 25;
        public double pickupSeconds = 1.5;
        public double deliverSeconds = 3;
        public double fuelPickupSeconds = 0.6;
        public double fuelLoadSeconds = 1;
        public double buildPercentPerSecond = 1.4;
        public int stunSeconds = 15;
        public int stomachSeconds = 30;
        public int orbs = 6;
        public int orbHits = 3;
        public double digestPercent = 2.5;
        public int devourSeconds = 40;
        public int spitSeconds = 12;
        public int slamSeconds = 9;
        public int rampageSeconds = 6;
        public int moveSeconds = 25;
        public int timeLimitMinutes = 25;
        public int rewardSeconds = 90;
        public int maxAlive = 28;
        public int startTokens = 25;
        public int fuelOnGround = 4;
        public int fuelRespawnSeconds = 6;
        public double fuelDropChance = 0.25;
        public Map<String, Double> tokens = new LinkedHashMap<>();

        public int token(String key) { Double v = tokens.get(key); return v == null ? 0 : (int) Math.round(v); }
        public double tokenD(String key) { Double v = tokens.get(key); return v == null ? 0 : v; }
    }

    /** One perk of the in-run shop. {@code max} 0 = a consumable bought any number of times. */
    public static final class Perk {
        public String id;
        public String name;
        public String icon;
        public int max;
        public int[] cost;
        public double per;
        public String lore;
        public String lore2;
        public String phase;

        public boolean consumable() { return max <= 0; }

        /** Cost of the next level (or of one use), or -1 when maxed. */
        public int costOf(int currentLevel) {
            if (consumable()) return cost.length == 0 ? 0 : cost[0];
            if (currentLevel >= max) return -1;
            return cost[Math.min(currentLevel, cost.length - 1)];
        }
    }

    /** One weighted row of a chest slot (or a guaranteed row: weight ignored). */
    public static final class Entry {
        public String item;
        public int count = 1;
        public double weight;
        /** Nobody may register it (yet): skipped quietly, and the self-test does not ask for it. */
        public boolean optional;
    }

    public static final class Rare { public String item; public double chance; }

    /** An attribute shard the paid chest can hold (hunting module ids), with its reference rarity. */
    public static final class Shard { public String id; public String rarity; }

    /** Rarity ladder of shards, lowest first (the Wheel of Embers climbs it). */
    public static final List<String> SHARD_RARITIES = List.of("COMMON", "UNCOMMON", "RARE", "EPIC", "LEGENDARY");

    /**
     * The two reward chests for one tier, the June-2025 model (audit K1-K23): the free chest is Crimson Essence; the
     * paid chest is the GUARANTEED part (Kraken shards, teeth, essence) + one weighted slot-1 roll + one weighted
     * slot-2 roll (the reference's per-tier weights) + the independent rares.
     */
    public static final class Loot {
        public String tier;
        public int[] freeEssence;
        public int[] paidEssence;
        public List<Entry> guaranteed = new ArrayList<>();
        public int bookLevel = 1;
        public List<Entry> slot1 = new ArrayList<>();
        public List<Entry> slot2 = new ArrayList<>();
        public List<Rare> rares = new ArrayList<>();
        /** The Wheel of Embers ladder: every shard a Leviathan chest can roll, with its rarity. */
        public List<Shard> shards = new ArrayList<>();

        public String shardRarityOf(String id) {
            for (Shard s : shards) if (s.id.equals(id)) return s.rarity;
            return null;
        }

        /** Every row of both slots and the guaranteed part. */
        public List<Entry> allEntries() {
            List<Entry> out = new ArrayList<>(guaranteed);
            out.addAll(slot1);
            out.addAll(slot2);
            return out;
        }

        /** Summed weight of a slot's rows that exist. */
        public static double weight(List<Entry> slot, java.util.function.Predicate<String> exists) {
            double w = 0;
            for (Entry e : slot) if (e.item != null && e.weight > 0 && exists.test(e.item)) w += e.weight;
            return w;
        }
    }

    private static final class TierFile { List<Tier> tiers = new ArrayList<>(); Fight fight = new Fight(); }

    public final List<Tier> tiers;
    public final Fight fight;
    public final List<Perk> perks;
    public final Map<String, Loot> loot = new LinkedHashMap<>();
    public final Map<String, String> npcSkins;

    private KCatalog(List<Tier> tiers, Fight fight, List<Perk> perks, List<Loot> loot, Map<String, String> skins) {
        this.tiers = List.copyOf(tiers);
        this.fight = fight;
        this.perks = List.copyOf(perks);
        for (Loot l : loot) this.loot.put(l.tier, l);
        this.npcSkins = skins == null ? Map.of() : skins;
    }

    public static KCatalog load(Reader tiers, Reader perks, Reader loot, Reader npcs) {
        Gson g = new Gson();
        TierFile tf = g.fromJson(tiers, TierFile.class);
        List<Perk> ps = g.fromJson(perks, new TypeToken<List<Perk>>() {}.getType());
        List<Loot> ls = g.fromJson(loot, new TypeToken<List<Loot>>() {}.getType());
        Map<String, String> skins = new LinkedHashMap<>();
        if (npcs != null) {
            JsonObject o = g.fromJson(npcs, JsonObject.class);
            if (o != null) for (var e : o.entrySet()) if (!e.getValue().isJsonNull()) skins.put(e.getKey(), e.getValue().getAsString());
        }
        return new KCatalog(tf.tiers, tf.fight == null ? new Fight() : tf.fight, ps, ls, skins);
    }

    public Tier tier(String idOrName) {
        if (idOrName == null) return null;
        String k = idOrName.trim().toLowerCase(java.util.Locale.ROOT);
        for (Tier t : tiers) if (t.id.equals(k) || t.name.equalsIgnoreCase(k) || String.valueOf(t.index + 1).equals(k)) return t;
        return null;
    }

    public Tier tier(int index) { return index >= 0 && index < tiers.size() ? tiers.get(index) : null; }

    public Perk perk(String id) {
        for (Perk p : perks) if (p.id.equals(id)) return p;
        return null;
    }
}
